 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objs = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            # A zero cell is enclosed if it cannot reach the outside of the
            # component's bounding box through other zero cells.
            box_zeros = {(y, x) for y in range(minr, maxr + 1)
                         for x in range(minc, maxc + 1) if (y, x) not in cells}
            exterior = set()
            flood = deque(p for p in box_zeros
                          if p[0] in (minr, maxr) or p[1] in (minc, maxc))
            exterior.update(flood)
            while flood:
                y, x = flood.popleft()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in box_zeros and p not in exterior:
                        exterior.add(p)
                        flood.append(p)
            rises = any(p not in exterior for p in box_zeros)
            objs.append({'cells': cells, 'color': color, 'rises': rises})

    def shifted(obj, dy):
        return {(r + dy, c) for r, c in obj['cells']}

    def can_move(i, dy):
        moved = shifted(objs[i], dy)
        if any(r < 0 or r >= h for r, c in moved):
            return False
        for j, other in enumerate(objs):
            if i != j and moved.intersection(other['cells']):
                return False
        return True

    # Let objects with enclosed holes rise and open shapes fall. Process the
    # leading objects first; repeat until every object is blocked.
    while True:
        changed = False
        order = sorted(range(len(objs)), key=lambda i:
                       (min(r for r, c in objs[i]['cells']) if objs[i]['rises']
                        else -max(r for r, c in objs[i]['cells'])))
        for i in order:
            dy = -1 if objs[i]['rises'] else 1
            if can_move(i, dy):
                objs[i]['cells'] = shifted(objs[i], dy)
                changed = True
        if not changed:
            break

    out = [[0] * w for _ in range(h)]
    for obj in objs:
        for r, c in obj['cells']:
            out[r][c] = obj['color']
    return out
